// Pedido del Panel de marketing (pestaña Paid). Valida antes de gastar o tocar Meta.
const b = ($json.body || $json) || {};
const accion = String(b.accion || '').trim();
const ahora = $now.setZone('America/Mexico_City');
const TOPE = 300; // MXN al día por campaña (cámbialo aquí; es el límite de gasto que se acepta desde el panel).
// Objetivos de campaña que se pueden crear.
const OBJETIVOS = ['reconocimiento', 'trafico', 'visitas_ig', 'interaccion', 'seguidores_fb', 'leads_sitio', 'leads_formulario'];
const conSitio = ['trafico', 'leads_sitio']; // necesitan landing del sitio de la marca
if (accion === 'crear' || accion === 'probar') {
  const p = b.propuesta || {};
  const marca = String(p.marca || '');
  if (!['marca-a', 'marca-b'].includes(marca)) throw new Error('Marca inválida: usa marca-a o marca-b.');
  const medio = String(p.medio || 'meta').toLowerCase();
  if (!['meta', 'google'].includes(medio)) throw new Error('Medio inválido: meta o google.');
  const presupuesto = Math.round(Number(p.presupuesto_diario));
  if (!(presupuesto >= 30)) throw new Error('El presupuesto diario mínimo es MXN 30.');
  if (presupuesto > TOPE) throw new Error('El tope es MXN ' + TOPE + ' al día por campaña; esta pide ' + presupuesto + '.');
  const nombre = String(p.nombre || '').trim().slice(0, 100);
  if (!nombre) throw new Error('Falta el nombre de la campaña.');
  let objetivo = String(p.objetivo || 'leads_sitio');
  if (objetivo === 'leads') objetivo = 'leads_sitio';
  if (!OBJETIVOS.includes(objetivo)) throw new Error('Objetivo no válido. Usa: ' + OBJETIVOS.join(', ') + '.');
  if (medio === 'google' && accion === 'probar') throw new Error('Google todavía no se puede probar: no hay conexión por API.');
  const dominio = marca === 'marca-a' ? /^https:\/\/(www\.)?marca-a\.com\.mx(\/|$|\?)/ : /^https:\/\/(www\.)?marca-b\.mx(\/|$|\?)/;
  let landing = String(p.landing || '').trim();
  if (medio === 'meta' && conSitio.includes(objetivo) && !dominio.test(landing)) throw new Error('La landing debe ser una página del sitio de la marca, con https.');
  if (landing && !dominio.test(landing)) throw new Error('La landing debe ser una página del sitio de la marca, con https.');
  if (!landing) landing = marca === 'marca-a' ? 'https://www.__DOMINIO_A__/' : 'https://www.__DOMINIO_B__/';
  // Interacción: se promociona un post que ya se publicó (no se crea anuncio nuevo).
  let post = null;
  if (objetivo === 'interaccion') {
    const fb = String(p.post_fb || '').trim();
    // Acepta la liga del post de Instagram o solo su código.
    const igTxt = String(p.post_ig || '').trim(), igM = igTxt.match(/instagram\.com\/(?:[^/]+\/)?(?:p|reel|tv)\/([A-Za-z0-9_-]+)/);
    const ig = igM ? igM[1] : igTxt;
    const red = p.red === 'instagram' || (p.red !== 'facebook' && ig && !fb) ? 'instagram' : 'facebook';
    if (red === 'facebook' && !/^\d+_\d+$/.test(fb)) throw new Error('Para interacción en Facebook elige un post publicado (falta su id de Facebook).');
    if (red === 'instagram' && !/^[A-Za-z0-9_-]{5,}$/.test(ig)) throw new Error('Para interacción en Instagram elige un post publicado (falta su liga de Instagram).');
    post = { red, fb, ig, post_id: String(p.post_id || '') };
  }
  const form_id = String(p.form_id || '').trim();
  if (objetivo === 'leads_formulario' && !/^\d+$/.test(form_id)) throw new Error('Para leads con formulario de Meta elige un formulario.');
  const ids = v => (Array.isArray(v) ? v : []).map(String).filter(x => /^\d+$/.test(x)).slice(0, 20);
  const incluir = ids(p.audiencias_incluir), excluir = ids(p.audiencias_excluir);
  const campana_id = (marca === 'marca-a' ? 'PAID-MA-' : 'PAID-MB-') + ahora.toFormat('yyMMdd-HHmmss');
  const probar = accion === 'probar';
  return [{ json: { accion, probar, campana_id, marca, medio, nombre, objetivo, presupuesto, landing, post, form_id, incluir, excluir, propuesta: p, propuesta_txt: JSON.stringify(p).slice(0, 8000), estado: medio === 'meta' ? 'creando' : 'encargada', actualizado: ahora.toFormat('yyyy-MM-dd HH:mm'), ruta: probar ? 3 : 0 } }];
}
if (accion === 'estado') {
  const campana_id = String(b.campana_id || '').trim();
  if (!campana_id) throw new Error('Falta campana_id.');
  if (typeof b.prender !== 'boolean') throw new Error('Falta prender: true o false.');
  return [{ json: { accion, campana_id, prender: b.prender, ruta: 1 } }];
}
if (accion === 'ver_imagen') {
  const campana_id = String(b.campana_id || '').trim();
  if (!campana_id) throw new Error('Falta campana_id.');
  return [{ json: { accion, campana_id, ruta: 2 } }];
}
throw new Error('Acción no válida: crear, probar, estado o ver_imagen.');

// Arma lo que se manda a Meta según el objetivo: campaña, conjunto, creativo y anuncio (todo en pausa).
// Con «probar» no se crea nada: arma un lote de revisiones para que Meta valide la combinación.
const V = $('Validar').first().json;
const leer = n => { try { return $(n).isExecuted ? $(n).first().json : null; } catch (e) { return null; } };
const R = leer('Redactar anuncio') || {}, P = leer('Crear imagen') || {};
const detalle = x => { const d = x && (x.detail || x.error || x.message); return (typeof d === 'string' ? d : JSON.stringify(d || x || {})).slice(0, 300); };
const C = {
  'marca-a': { act: '__META_AD_ACCOUNT_A__', page: '__META_PAGE_ID_A__', ig: '__META_IG_ID_A__', ig_usuario: '__IG_USUARIO_A__', pixel: '__META_PIXEL_ID_A__', dominio: '__DOMINIO_A__', imagen_prueba: 'de8bf018b17af09cf6b3022bccb4f1ff' },
  'marca-b': { act: '__META_AD_ACCOUNT_B__', page: '__META_PAGE_ID_B__', ig: '__META_IG_ID_B__', ig_usuario: '__IG_USUARIO_B__', pixel: '__META_PIXEL_ID_B__', dominio: '__DOMINIO_B__', imagen_prueba: '6fd711f4de789bf1f2e0a5792d984a1f' },
}[V.marca];
const OBJ = V.objetivo;
const nuevo = OBJ !== 'interaccion'; // los demás llevan anuncio nuevo (texto + imagen)
if (!V.probar && nuevo) {
  if (!R.textos || !R.copy) return [{ json: { ok: false, error: 'No se pudo redactar el anuncio: ' + detalle(R) } }];
  if (!P.pieza_jpeg_b64) return [{ json: { ok: false, error: 'No se pudo crear la imagen: ' + detalle(P) } }];
}
const slug = s => String(s).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '').slice(0, 40);
const utm = u => u + (u.includes('?') ? '&' : '?') + 'utm_source=meta&utm_medium=paid_social&utm_campaign=' + slug(V.nombre) + '&utm_content=' + V.campana_id.toLowerCase();
const link = utm(V.landing);
const copy = V.probar ? 'Prueba de validación (no se publica).' : String(R.copy || '').split('\n').filter(l => !/(https?:\/\/|www\.)\S+/i.test(l)).join('\n').replace(/\n{3,}/g, '\n\n').trim();
const titular = String((R.textos && R.textos.titular) || V.nombre).slice(0, 80);
const nombre = '[Agente] ' + V.nombre;
// Objetivo de Meta, meta de optimización y destino (Graph API v26).
const M = {
  reconocimiento: { objective: 'OUTCOME_AWARENESS', optimization_goal: 'REACH', promoted_object: { page_id: C.page } },
  trafico: { objective: 'OUTCOME_TRAFFIC', optimization_goal: 'LANDING_PAGE_VIEWS', destination_type: 'WEBSITE', pixel: true },
  visitas_ig: { objective: 'OUTCOME_TRAFFIC', optimization_goal: 'PROFILE_VISIT', destination_type: 'INSTAGRAM_PROFILE', promoted_object: { page_id: C.page }, plataformas: ['instagram'] },
  interaccion: { objective: 'OUTCOME_ENGAGEMENT', optimization_goal: 'POST_ENGAGEMENT', destination_type: 'ON_POST' },
  seguidores_fb: { objective: 'OUTCOME_ENGAGEMENT', optimization_goal: 'PAGE_LIKES', destination_type: 'ON_PAGE', promoted_object: { page_id: C.page }, plataformas: ['facebook'] },
  leads_sitio: { objective: 'OUTCOME_LEADS', optimization_goal: 'OFFSITE_CONVERSIONS', destination_type: 'WEBSITE', promoted_object: { pixel_id: C.pixel, custom_event_type: 'LEAD' }, pixel: true },
  leads_formulario: { objective: 'OUTCOME_LEADS', optimization_goal: 'LEAD_GENERATION', destination_type: 'ON_AD', promoted_object: { page_id: C.page } },
}[OBJ];
const edad = Math.max(18, Math.min(65, Number((V.propuesta || {}).edad_min) || 18));
// Con audiencias para incluir se apaga Advantage+ audiencia: si no, Meta las toma solo como sugerencia.
const targeting = { geo_locations: { countries: ['MX'] }, age_min: edad, targeting_automation: { advantage_audience: V.incluir.length ? 0 : 1 } };
if (V.incluir.length) targeting.custom_audiences = V.incluir.map(id => ({ id }));
if (V.excluir.length) targeting.excluded_custom_audiences = V.excluir.map(id => ({ id }));
if (M.plataformas) { targeting.publisher_platforms = M.plataformas; if (M.plataformas[0] === 'facebook') targeting.facebook_positions = ['feed']; else targeting.instagram_positions = ['stream', 'story', 'reels']; }
const campana = { name: nombre, objective: M.objective, status: 'PAUSED', special_ad_categories: [], daily_budget: String(V.presupuesto * 100), bid_strategy: 'LOWEST_COST_WITHOUT_CAP' };
const conjunto = { name: nombre + ' · público', billing_event: 'IMPRESSIONS', optimization_goal: M.optimization_goal, targeting, status: 'PAUSED' };
if (M.destination_type) conjunto.destination_type = M.destination_type;
if (M.promoted_object) conjunto.promoted_object = M.promoted_object;
// Creativo.
const ctaSitio = OBJ === 'leads_sitio' ? (V.marca === 'marca-a' ? 'APPLY_NOW' : 'CONTACT_US') : 'LEARN_MORE';
let creativo;
if (OBJ === 'interaccion') {
  creativo = V.post.red === 'facebook'
    ? { name: nombre + ' · post', object_story_id: V.post.fb, instagram_user_id: C.ig }
    : { name: nombre + ' · post', object_id: C.page, instagram_user_id: C.ig, source_instagram_media_id: '__IGMEDIA__' };
} else {
  const ld = { image_hash: '__HASH__', message: copy, name: titular };
  if (OBJ === 'seguidores_fb') Object.assign(ld, { link: 'https://www.facebook.com/' + C.page, call_to_action: { type: 'LIKE_PAGE', value: { page: C.page } } });
  else if (OBJ === 'leads_formulario') Object.assign(ld, { link: 'https://fb.me/', call_to_action: { type: 'SIGN_UP', value: { lead_gen_form_id: V.form_id } } });
  else if (OBJ === 'visitas_ig') Object.assign(ld, { link: 'https://www.instagram.com/' + C.ig_usuario + '/', call_to_action: { type: 'VIEW_INSTAGRAM_PROFILE' } });
  else Object.assign(ld, { link, call_to_action: { type: ctaSitio, value: { link } } });
  creativo = { name: nombre + ' · creativo', object_story_spec: { page_id: C.page, instagram_user_id: C.ig, link_data: ld } };
}
const anuncio = { name: nombre + ' · anuncio', status: 'PAUSED' };
if (M.pixel) { anuncio.conversion_domain = C.dominio; anuncio.tracking_specs = [{ 'action.type': ['offsite_conversion'], 'fb_pixel': [C.pixel] }]; }
const enc = o => Object.entries(o).map(([k, v]) => k + '=' + encodeURIComponent(typeof v === 'string' ? v : JSON.stringify(v)))
  .join('&').replace(/%7Bresult%3D([a-z]+)%3A%24\.id%7D/g, '{result=$1:$.id}');
const batch = JSON.stringify([
  { method: 'POST', name: 'campana', omit_response_on_success: false, relative_url: C.act + '/campaigns', body: enc(campana) },
  { method: 'POST', name: 'conjunto', omit_response_on_success: false, relative_url: C.act + '/adsets', body: enc(Object.assign({ campaign_id: '{result=campana:$.id}' }, conjunto)) },
  { method: 'POST', name: 'creativo', omit_response_on_success: false, relative_url: C.act + '/adcreatives', body: enc(creativo) },
  { method: 'POST', name: 'anuncio', omit_response_on_success: false, relative_url: C.act + '/ads', body: enc(Object.assign({ adset_id: '{result=conjunto:$.id}', creative: { creative_id: '{result=creativo:$.id}' } }, anuncio)) },
]);
// Prueba sin crear nada, en un solo lote (Meta no acepta un conjunto con la campaña anidada):
// (1) la campaña con validate_only, (2) la estimación de entrega con la misma meta, público y objeto promovido
// (revisa que el conjunto sea válido), (3) la vista previa del creativo (lo valida sin guardarlo).
const qs = o => Object.entries(o).map(([k, v]) => k + '=' + encodeURIComponent(typeof v === 'string' ? v : JSON.stringify(v))).join('&');
const estimacion = { optimization_goal: M.optimization_goal, targeting_spec: targeting };
if (M.promoted_object) estimacion.promoted_object = M.promoted_object;
const prueba_batch = JSON.stringify([
  { method: 'POST', name: 'campana', relative_url: C.act + '/campaigns', body: enc(Object.assign({}, campana, { execution_options: ['validate_only'] })) },
  { method: 'GET', name: 'conjunto', relative_url: C.act + '/delivery_estimate?' + qs(estimacion) },
  { method: 'GET', name: 'vista', relative_url: C.act + '/generatepreviews?' + qs({ ad_format: OBJ === 'visitas_ig' ? 'INSTAGRAM_STANDARD' : 'MOBILE_FEED_STANDARD', creative: creativo }) },
]).split('__HASH__').join(C.imagen_prueba);
const ig_shortcode = OBJ === 'interaccion' && V.post.red === 'instagram' ? V.post.ig : '';
return [{ json: { ok: true, probar: V.probar, objetivo: OBJ, marca: V.marca, act: C.act, ig: C.ig, sube_imagen: nuevo, ig_shortcode, batch, prueba_batch,
  bytes: P.pieza_jpeg_b64 || '', titular, copy, link: ['trafico', 'leads_sitio', 'reconocimiento'].includes(OBJ) ? link : '', costo_usd: Number(P.costo_usd) || 0 } }];

// Lee lo que contestó Meta. Todo nace en pausa: no se gasta nada hasta que el dueño la prenda.
const V = $('Validar').first().json, M = $('Preparar Meta').first().json;
const msg = x => (x && x.error && (x.error.error_user_msg || x.error.error_user_title || x.error.message)) || '';
const leer = n => { try { return $(n).isExecuted ? $(n).first().json : null; } catch (e) { return null; } };
let error = '', ids = {};
if (!M.ok) error = M.error;
else {
  const img = leer('Imagen Marca A') || leer('Imagen Marca B') || {};
  const medios = leer('Medios IG Marca A') || leer('Medios IG Marca B') || {};
  if (M.sube_imagen && (msg(img) || !img.images)) error = 'Meta no aceptó la imagen: ' + (msg(img) || JSON.stringify(img).slice(0, 200));
  else if (M.ig_shortcode && !((medios.data || []).some(m => m.shortcode === M.ig_shortcode))) error = 'No encontré ese post en el Instagram de la marca (solo se buscan los últimos 100).';
  else {
    const items = $input.all().map(i => i.json || {});
    if (items.length === 1 && items[0].error) error = 'Meta rechazó la creación: ' + msg(items[0]);
    else {
      const nombres = ['campaign', 'adset', 'creative', 'ad'], que = ['la campaña', 'el público', 'el creativo', 'el anuncio'];
      items.forEach((x, i) => {
        let body = {}; try { body = JSON.parse(x.body || '{}'); } catch (e) {}
        if (Number(x.code) !== 200 || body.error || !body.id) { if (!error) error = 'Meta rechazó ' + (que[i] || 'un paso') + ': ' + (msg(body) || ('código ' + x.code)); }
        else ids[nombres[i]] = body.id;
      });
      if (!error && Object.keys(ids).length < 4) error = 'Meta no confirmó todos los pasos.';
    }
  }
}
const parcial = error && ids.campaign ? ' Quedó una campaña incompleta en pausa en Meta (' + ids.campaign + '); no gasta, pero conviene borrarla.' : '';
return [{ json: { ok: !error, error: error ? error + parcial : '', ids, bytes: M.ok ? M.bytes : '', titular: M.titular || '', copy: M.copy || '', link: M.link || '', costo_usd: M.costo_usd || 0, campana_id: V.campana_id, archivo: V.campana_id + '.jpg', con_imagen: !!(M.ok && M.bytes) } }];

// Google Ads todavía no tiene conexión por API para crear campañas: se guarda la propuesta y el panel abre el encargo.
const V = $('Validar').first().json;
return [{ json: { respuesta: { ok: true, mensaje: 'Guardé la propuesta de Google Ads. Google todavía no está conectado para crearla solo: queda como encargo y la armo en pausa con tu OK.', data: { campana_id: V.campana_id, estado: 'encargada' } } } }];

// Respuesta única que lee el panel.
for (const n of ['Fila de campaña', 'Fila de estado', 'Pedido Google', 'Imagen lista', 'Resultado prueba']) {
  try { if ($(n).isExecuted) return [{ json: $(n).first().json.respuesta }]; } catch (e) {}
}
return [{ json: { ok: false, mensaje: 'Sin respuesta.' } }];

// Prender o apagar una campaña de Meta creada por el agente. Prender activa anuncio, público y campaña; apagar pausa la campaña.
const S = $('Validar').first().json, row = $input.first().json || {};
if (!row.campana_id) throw new Error('No encontré la campaña ' + S.campana_id + '.');
if (row.medio !== 'meta') throw new Error('Por ahora solo las campañas de Meta se prenden desde el panel.');
if (!row.meta_campaign_id || !row.meta_adset_id || !row.meta_ad_id) throw new Error('Esta campaña no se terminó de crear en Meta; no se puede prender.');
if (Number(row.presupuesto) > 300) throw new Error('La campaña pasa el tope de MXN 300 al día.');
const st = S.prender ? 'ACTIVE' : 'PAUSED';
const objs = S.prender ? [row.meta_ad_id, row.meta_adset_id, row.meta_campaign_id] : [row.meta_campaign_id];
const batch = JSON.stringify(objs.map(id => ({ method: 'POST', relative_url: id, body: 'status=' + st })));
return [{ json: { batch, marca: row.marca, prender: S.prender, row } }];

// Resultado de prender o apagar.
const P = $('Preparar estado').first().json;
const items = $input.all().map(i => i.json || {});
const msg = x => (x && x.error && (x.error.error_user_msg || x.error.message)) || '';
let error = '';
if (items.length === 1 && items[0].error) error = msg(items[0]);
items.forEach(x => { let body = {}; try { body = JSON.parse(x.body || '{}'); } catch (e) {} if (!error && (Number(x.code) !== 200 || body.error)) error = msg(body) || ('código ' + x.code); });
const estado = error ? P.row.estado : (P.prender ? 'activa' : 'en pausa');
const respuesta = error
  ? { ok: false, mensaje: 'Meta no aceptó el cambio: ' + error, data: { campana_id: P.row.campana_id, estado } }
  : { ok: true, mensaje: P.prender ? 'Campaña prendida. Meta la revisa antes de mostrarla (suele tardar de minutos a unas horas).' : 'Campaña apagada.', data: { campana_id: P.row.campana_id, estado } };
return [{ json: { campana_id: P.row.campana_id, nombre: P.row.nombre, marca: P.row.marca, presupuesto: P.row.presupuesto, estado, error, respuesta, actualizado: $now.setZone('America/Mexico_City').toFormat('yyyy-MM-dd HH:mm') } }];

// Imagen del anuncio para el panel.
const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
return [{ json: { respuesta: { ok: true, data: { imagen: 'data:image/jpeg;base64,' + buf.toString('base64') } } } }];

// Lo que se guarda en paid_campanas y lo que ve el panel.
const V = $('Validar').first().json, R = $('Revisar Meta').first().json, T = $input.first().json || {};
const fotos = (T.result && T.result.photo) || T.photo || [];
const imagen = R.ok && fotos.length ? fotos[fotos.length - 1].file_id : '';
const fila = { estado: R.ok ? 'en pausa' : 'error', titular: R.titular, copy: R.copy, landing: R.link || V.landing, imagen, meta_campaign_id: R.ids.campaign || '', meta_adset_id: R.ids.adset || '', meta_creative_id: R.ids.creative || '', meta_ad_id: R.ids.ad || '', costo_usd: R.costo_usd, error: R.error, actualizado: $now.setZone('America/Mexico_City').toFormat('yyyy-MM-dd HH:mm') };
const respuesta = R.ok
  ? { ok: true, mensaje: 'Campaña creada en pausa en Meta. Revisa la imagen y el texto; no gasta nada hasta que la prendas.', data: Object.assign({ campana_id: V.campana_id }, fila) }
  : { ok: false, mensaje: R.error, data: Object.assign({ campana_id: V.campana_id }, fila) };
return [{ json: Object.assign({ campana_id: V.campana_id, respuesta }, fila) }];

// Resultado de la prueba: Meta revisó la campaña (validate_only), estimó la entrega del conjunto y armó la vista previa del creativo, sin crear nada.
const M = $('Preparar Meta').first().json;
if (!M.ok) return [{ json: { respuesta: { ok: false, mensaje: M.error } } }];
const NOMBRE = { reconocimiento: 'Reconocimiento', trafico: 'Tráfico al sitio', visitas_ig: 'Visitas al perfil de Instagram', interaccion: 'Interacción con un post', seguidores_fb: 'Seguidores de Facebook', leads_sitio: 'Leads en el sitio', leads_formulario: 'Leads con formulario de Meta' }[M.objetivo] || M.objetivo;
const medios = (() => { try { return ($('Medios IG Marca A (prueba)').isExecuted ? $('Medios IG Marca A (prueba)') : $('Medios IG Marca B (prueba)')).first().json; } catch (x) { return {}; } })();
if (M.ig_shortcode && !((medios.data || []).some(m => m.shortcode === M.ig_shortcode))) return [{ json: { respuesta: { ok: false, mensaje: NOMBRE + ': no encontré ese post en el Instagram de la marca.' } } }];
const items = $input.all().map(i => i.json || {});
const err = x => { const e = (x && x.error) || {}; return e.error_user_msg || e.error_user_title || e.message ? (e.error_user_msg || e.error_user_title || e.message) + (e.error_subcode ? ' (' + e.code + '/' + e.error_subcode + ')' : '') : ''; };
if (items.length === 1 && items[0].error) return [{ json: { respuesta: { ok: false, mensaje: NOMBRE + ': Meta no aceptó la prueba: ' + err(items[0]) } } }];
const body = i => { try { return JSON.parse((items[i] || {}).body || '{}'); } catch (e) { return {}; } };
const c = body(0), a = body(1), v = body(2);
const problemas = [];
if (!(c.success === true || c.id)) problemas.push('la campaña: ' + (err(c) || 'sin respuesta'));
if (!(a.data && a.data.length)) problemas.push('el público y la meta: ' + (err(a) || 'sin estimación'));
if (!(v.data && v.data[0] && v.data[0].body)) problemas.push('el anuncio: ' + (err(v) || 'sin vista previa'));
